@import "tailwindcss";

:root {
  --background: #f5f7fb;
  --surface: #ffffff;
  --foreground: #16213a;
  --muted: #6b7a90;
  --line: #e4e9f2;
  --brand: #2f6bff;
  --brand-soft: #e9f0ff;
  --brand-ink: #1b47b8;
  --ok: #15803d;
  --ok-soft: #e7f7ec;
  --warn: #b45309;
  --warn-soft: #fff4e5;
  --bad: #c0262d;
  --bad-soft: #fdecec;
}

@theme inline {
  --color-background: var(--background);
  --color-surface: var(--surface);
  --color-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-line: var(--line);
  --color-brand: var(--brand);
  --color-brand-soft: var(--brand-soft);
  --color-brand-ink: var(--brand-ink);
  --color-ok: var(--ok);
  --color-ok-soft: var(--ok-soft);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-bad: var(--bad);
  --color-bad-soft: var(--bad-soft);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

html {
  background: var(--background);
}
body {
  background:
    radial-gradient(900px 500px at 8% -10%, #e4ecff 0%, transparent 60%),
    radial-gradient(700px 400px at 100% 0%, #fdeeea 0%, transparent 55%),
    var(--background);
  background-attachment: fixed;
  color: var(--foreground);
  font-family: var(--font-geist-sans), system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}

.card {
  @apply rounded-2xl border border-line bg-surface p-4;
  box-shadow: 0 1px 2px rgba(22, 33, 58, 0.04), 0 8px 24px -16px rgba(22, 33, 58, 0.18);
}
.chip {
  @apply inline-flex items-center gap-1.5 rounded-full border border-line bg-surface px-3 py-1 text-sm text-foreground transition hover:border-brand hover:text-brand;
}
.tag {
  @apply inline-block rounded-md bg-brand-soft px-2 py-0.5 text-xs font-medium text-brand-ink;
}
.btn {
  @apply inline-flex items-center justify-center gap-2 rounded-full bg-brand px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-brand-ink disabled:opacity-50;
}
.btn-ghost {
  @apply inline-flex items-center justify-center gap-2 rounded-full border border-line bg-surface px-5 py-2.5 text-sm font-semibold transition hover:border-brand hover:text-brand;
}
.stat {
  @apply rounded-2xl bg-background px-4 py-3;
}
.stat .label {
  @apply text-xs text-muted;
}
.stat .value {
  @apply mt-1 text-2xl font-semibold tracking-tight;
}
.icon-tile {
  @apply inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-brand-soft text-brand-ink;
}
.eyebrow {
  @apply text-sm font-semibold text-brand;
}
.prose-sm p { @apply my-1; }
.prose-sm ul { @apply my-1 list-disc pl-5; }
.prose-sm ol { @apply my-1 list-decimal pl-5; }
.prose-sm strong { @apply font-semibold; }
.prose-sm code { @apply rounded bg-background px-1 text-[0.9em]; }

