          </div>
          {d.offers.map((o, i) => (
            <div key={o.id} className="mt-1 flex items-center justify-between text-sm">
              <span>{i + 1}. {o.program}</span>
              <span className="text-xs text-muted">${(o.stipend_usd ?? 0).toLocaleString()} · {o.years_guaranteed} yrs</span>
            </div>
