"use client";

import { useEffect, useRef } from "react";

/** Leaflet via CDN (no bundler config, no API key) with OpenStreetMap tiles. */
type Place = { lat: number; lng: number; city?: string; region?: string; climate?: { jan_low_c?: number; jul_high_c?: number; rain_days?: number }; living?: { cost_of_living?: string } };
type Item = { name: string; short?: string; deadline?: string; advisors: number; status: string; place?: Place };

declare global {
  interface Window {
    L?: any; // eslint-disable-line @typescript-eslint/no-explicit-any
  }
}

function loadLeaflet(): Promise<void> {
  if (typeof window === "undefined") return Promise.resolve();
  if (window.L) return Promise.resolve();
  return new Promise((resolve) => {
    if (!document.querySelector("link[data-leaflet]")) {
      const css = document.createElement("link");
      css.rel = "stylesheet";
      css.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
      css.setAttribute("data-leaflet", "1");
      document.head.appendChild(css);
    }
    const s = document.createElement("script");
    s.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
    s.onload = () => resolve();
    document.head.appendChild(s);
  });
}

export function ProgramMap({ items, selected, onSelect }: { items: Item[]; selected?: string; onSelect: (name: string) => void }) {
  const ref = useRef<HTMLDivElement>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const mapRef = useRef<any>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const markersRef = useRef<Record<string, any>>({});

  useEffect(() => {
    let cancelled = false;
    loadLeaflet().then(() => {
      if (cancelled || !ref.current || mapRef.current) return;
      const L = window.L;
      const map = L.map(ref.current, { scrollWheelZoom: false, zoomControl: true });
      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", { attribution: "&copy; OpenStreetMap contributors", maxZoom: 18 }).addTo(map);
      mapRef.current = map;
      const pts: [number, number][] = [];
      for (const it of items) {
        if (!it.place) continue;
        const { lat, lng } = it.place;
        pts.push([lat, lng]);
        const icon = L.divIcon({
          className: "",
          html: `<div style="background:#2f6bff;color:#fff;border-radius:999px;padding:4px 10px;font:600 12px system-ui;white-space:nowrap;box-shadow:0 2px 8px rgba(22,33,58,.25)">${it.short ?? it.name}</div>`,
          iconAnchor: [30, 14],
        });
        const c = it.place.climate ?? {};
        const m = L.marker([lat, lng], { icon }).addTo(map);
        m.bindPopup(
          `<div style="font:13px system-ui;min-width:200px"><b>${it.name}</b><br/>${it.place.city ?? ""}${it.place.region ? ", " + it.place.region : ""}<br/>` +
            (c.jan_low_c != null ? `Jan low ${c.jan_low_c}°C · Jul high ${c.jul_high_c}°C · ${c.rain_days} rain days<br/>` : "") +
            (it.place.living?.cost_of_living ? `Cost of living: ${it.place.living.cost_of_living}<br/>` : "") +
            (it.deadline ? `Deadline: ${it.deadline}<br/>` : "") +
            `${it.advisors} advisors · ${it.status}</div>`,
        );
        m.on("click", () => onSelect(it.name));
        markersRef.current[it.name] = m;
      }
      if (pts.length) map.fitBounds(pts, { padding: [40, 40], maxZoom: 6 });
    });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items.length]);

  useEffect(() => {
    const m = selected ? markersRef.current[selected] : null;
    if (m && mapRef.current) {
      mapRef.current.flyTo(m.getLatLng(), 8, { duration: 0.8 });
      m.openPopup();
    }
  }, [selected]);

  return <div ref={ref} className="h-[520px] w-full overflow-hidden rounded-2xl border border-line" />;
}

"use client";

import { useState } from "react";
import { Icon } from "@/components/Icons";
import type { Key } from "@/lib/i18n";
import { ProgramMap } from "./ProgramMap";
import { RequirementsCard } from "./Cards";

type T = (k: Key) => string;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type State = any;

function statusOf(p: State) {
  if (p.final?.passed) return "complete";
  if (p.final) return "needs_review";
  if (p.requirements) return "researched";
  return "not_started";
}

/** Programs page: the same programs as a list, as place cards, or on a map. */
export function ProgramsView({ state, t, onAction }: { state: State; t: T; onAction: (m: string) => void }) {
  const [mode, setMode] = useState<"list" | "cards" | "map">("cards");
  const [selected, setSelected] = useState<string | undefined>();
  const places = state.places ?? {};
  const items = state.programs.map((p: State) => ({
    name: p.name,
    short: p.short,
    deadline: p.requirements?.facts?.find((f: State) => f.key === "deadline")?.value?.split(/[,(]/)[0]?.trim(),
    advisors: p.advisors?.advisors?.length ?? 0,
    facts: p.requirements?.facts?.length ?? 0,
    status: statusOf(p),
    place: places[p.name],
    requirements: p.requirements,
  }));
  const modes = [
    ["list", t("viewList")],
    ["cards", t("viewCards")],
    ["map", t("viewMap")],
  ] as const;
  return (
    <>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex gap-1 rounded-full border border-line bg-surface p-1">
          {modes.map(([k, label]) => (
            <button key={k} className={`rounded-full px-3 py-1 text-sm ${mode === k ? "bg-brand text-white" : "text-muted hover:text-foreground"}`} onClick={() => setMode(k)}>
              {label}
            </button>
          ))}
        </div>
        <button className="chip" onClick={() => onAction(t("quick5"))}>
          <Icon.compass size={14} className="text-brand" /> {t("quick5")}
        </button>
      </div>

      {mode === "map" && (
        <>
          <ProgramMap items={items} selected={selected} onSelect={setSelected} />
          <div className="grid gap-3 md:grid-cols-3">
            {items.map((it: State) => (
              <PlaceCard key={it.name} it={it} t={t} active={selected === it.name} onClick={() => setSelected(it.name)} compact />
            ))}
          </div>
        </>
      )}

      {mode === "cards" && (
        <div className="grid gap-3 md:grid-cols-2">
          {items.map((it: State) => (
            <PlaceCard key={it.name} it={it} t={t} active={false} onClick={() => { setSelected(it.name); setMode("map"); }} />
          ))}
        </div>
      )}

      {mode === "list" &&
        items.map((it: State) => it.requirements && <RequirementsCard key={it.name} card={{ kind: "requirements", program: it.name, ...it.requirements }} t={t} />)}
      {mode === "list" && items.every((it: State) => !it.requirements) && <p className="text-sm text-muted">{t("nothingYet")}</p>}
    </>
  );
}

function PlaceCard({ it, t, active, onClick, compact }: { it: State; t: T; active: boolean; onClick: () => void; compact?: boolean }) {
  const p = it.place;
  const c = p?.climate;
  const statusColor = it.status === "complete" ? "text-ok" : it.status === "needs_review" ? "text-warn" : "text-muted";
  return (
    <button onClick={onClick} className={`card text-left transition hover:border-brand ${active ? "border-brand" : ""}`}>
      <div className="flex items-start justify-between gap-2">
        <div>
          <div className="font-semibold">{it.name}</div>
          <div className="text-xs text-muted">
            {p ? `${p.city}, ${p.region}` : "—"} · {it.deadline ? `${t("deadline")} ${it.deadline}` : ""}
          </div>
        </div>
        <span className={`text-xs font-medium ${statusColor}`}>{t(`status_${it.status}` as Key)}</span>
      </div>
      {c && (
        <div className="mt-3 grid grid-cols-3 gap-2 text-center">
          <Mini label={t("janLow")} value={`${c.jan_low_c}°C`} />
          <Mini label={t("julHigh")} value={`${c.jul_high_c}°C`} />
          <Mini label={t("rainDays")} value={`${c.rain_days}`} />
        </div>
      )}
      {p?.living && !compact && (
        <div className="mt-3 space-y-1 text-sm">
          <div>
            <span className="tag mr-2">{t("costOfLiving")}</span>
            {p.living.cost_of_living} · {p.living.rent_note}
          </div>
          <div className="text-muted">{p.living.city_feel}</div>
          <div className="text-muted">{p.living.international_note}</div>
          <div className="text-xs text-muted">
            {p.living.caveat}{" "}
            <a className="text-brand underline" href={p.verify_url} target="_blank" rel="noreferrer" onClick={(e) => e.stopPropagation()}>
              {t("verify")}
            </a>
            {c && <span> · {t("climateSource")}: Open-Meteo {c.year}</span>}
          </div>
        </div>
      )}
      <div className="mt-3 text-xs text-muted">
        {it.facts} {t("facts")} · {it.advisors} {t("advisors").toLowerCase()}
      </div>
    </button>
  );
}

function Mini({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-xl bg-background px-2 py-2">
      <div className="text-[11px] text-muted">{label}</div>
      <div className="text-sm font-semibold">{value}</div>
    </div>
  );
}

"use client";

import Image from "next/image";
import { useEffect, useRef, useState } from "react";
import { Icon } from "@/components/Icons";
import { API, APPLICANT } from "@/lib/api";
import type { Key, Lang } from "@/lib/i18n";

type Q = { id: string; stage: string; question: string; why: string; strong_answer_includes: string[] };
type Plan = { advisor: string; program: string; questions: Q[]; stages: string[]; caveat: string; answers: Eval[] };
type Eval = { question_id: string; answer: string; scores: { fit: number; depth: number; clarity: number }; feedback: string; follow_up: string };

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type State = any;

/** Voice mock interview. Browser speech synthesis asks; browser speech recognition (Chrome) listens; typing always works. */
export function Interview({ state, lang, t }: { state: State; lang: Lang; t: (k: Key) => string }) {
  const programs: State[] = state?.programs ?? [];
  const [program, setProgram] = useState<string>(programs[0]?.name ?? "");
  const advisors: State[] = programs.find((p: State) => p.name === program)?.advisors?.advisors ?? [];
  const [advisor, setAdvisor] = useState<string>(advisors[0]?.name ?? "");
  const [plan, setPlan] = useState<Plan | null>(null);
  const [idx, setIdx] = useState(0);
  const [answer, setAnswer] = useState("");
  const [status, setStatus] = useState<"idle" | "loading" | "speaking" | "listening" | "evaluating">("idle");
  const [evals, setEvals] = useState<Eval[]>([]);
  const [error, setError] = useState<string | null>(null);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const recRef = useRef<any>(null);
  const L = lang === "zh";

  useEffect(() => {
    if (!advisors.find((a: State) => a.name === advisor)) setAdvisor(advisors[0]?.name ?? "");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [program]);

  const canListen = typeof window !== "undefined" && ("SpeechRecognition" in window || "webkitSpeechRecognition" in window);

  function speak(text: string) {
    if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = "en-US";
    u.rate = 0.98;
    const voices = window.speechSynthesis.getVoices();
    const v = voices.find((x) => /en-US/.test(x.lang) && /Samantha|Google US English|Aria|Jenny/.test(x.name)) ?? voices.find((x) => /en-US/.test(x.lang));
    if (v) u.voice = v;
    u.onstart = () => setStatus("speaking");
    u.onend = () => setStatus("idle");
    window.speechSynthesis.speak(u);
  }

  async function start() {
    setError(null);
    setStatus("loading");
    const r = await fetch(`${API}/api/applicants/${APPLICANT}/interview/plan`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ program, advisor }) });
    if (!r.ok) {
      setError(`HTTP ${r.status}`);
      setStatus("idle");
      return;
    }
    const p: Plan = await r.json();
    setPlan(p);
    setEvals(p.answers ?? []);
    setIdx(0);
    setStatus("idle");
    speak(p.questions[0].question);
  }

  function listen() {
    if (!canListen) return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    const rec = new SR();
    rec.lang = "en-US";
    rec.interimResults = true;
    rec.continuous = true;
    let final = "";
    rec.onresult = (e: { resultIndex: number; results: ArrayLike<{ 0: { transcript: string }; isFinal: boolean }> }) => {
      let interim = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const res = e.results[i];
        if (res.isFinal) final += res[0].transcript + " ";
        else interim += res[0].transcript;
      }
      setAnswer((final + interim).trim());
    };
    rec.onend = () => setStatus("idle");
    rec.start();
    recRef.current = rec;
    setStatus("listening");
  }

  function stopListening() {
    recRef.current?.stop();
    setStatus("idle");
  }

  async function submit() {
    if (!plan || !answer.trim()) return;
    stopListening();
    setStatus("evaluating");
    const q = plan.questions[idx];
    const r = await fetch(`${API}/api/applicants/${APPLICANT}/interview/answer`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ program, advisor, question_id: q.id, answer }),
    });
    setStatus("idle");
    if (!r.ok) {
      setError(r.status === 429 ? (L ? "这场面试的评估次数已用完。" : "Evaluation limit reached for this interview.") : `HTTP ${r.status}`);
      return;
    }
    const ev: Eval = await r.json();
    setEvals((x) => [...x, ev]);
    setAnswer("");
    speak(ev.feedback + " " + ev.follow_up);
  }

  function next() {
    if (!plan) return;
    const n = Math.min(idx + 1, plan.questions.length - 1);
    setIdx(n);
    setAnswer("");
    speak(plan.questions[n].question);
  }

  const q = plan?.questions[idx];
  const done = evals.filter((e) => e.question_id === q?.id);
  const avg = (k: "fit" | "depth" | "clarity") => (evals.length ? (evals.reduce((s, e) => s + e.scores[k], 0) / evals.length).toFixed(1) : "–");

  return (
    <div className="space-y-4">
      <div className="card flex flex-wrap items-end gap-3">
        <label className="text-sm">
          <div className="text-xs text-muted">{t("programs")}</div>
          <select className="mt-1 rounded-xl border border-line px-3 py-2" value={program} onChange={(e) => setProgram(e.target.value)}>
            {programs.map((p: State) => (
              <option key={p.key} value={p.name}>
                {p.name}
              </option>
            ))}
          </select>
        </label>
        <label className="text-sm">
          <div className="text-xs text-muted">{t("advisors")}</div>
          <select className="mt-1 rounded-xl border border-line px-3 py-2" value={advisor} onChange={(e) => setAdvisor(e.target.value)}>
            {advisors.map((a: State) => (
              <option key={a.name} value={a.name}>
                {a.name}
              </option>
            ))}
          </select>
        </label>
        <button className="btn" onClick={start} disabled={!advisor || status === "loading"}>
          {status === "loading" ? t("thinking") : t("startInterview")}
        </button>
        {!canListen && <span className="text-xs text-muted">{t("voiceChromeOnly")}</span>}
        {error && <span className="text-xs text-bad">{error}</span>}
      </div>

      {plan && q && (
        <div className="grid gap-4 md:grid-cols-[1fr_1.2fr]">
          <div className="card">
            <div className="flex items-center gap-3">
              <div className={`relative rounded-full p-1 ${status === "speaking" ? "ring-4 ring-brand-soft" : ""}`}>
                <Image src="/mascot-bot.png" alt="" width={72} height={96} className="h-20 w-auto" />
              </div>
              <div>
                <div className="text-xs text-muted">
                  {plan.advisor} · {t("stage")} {plan.stages.indexOf(q.stage) + 1}/{plan.stages.length} · {q.stage.replace(/_/g, " ")}
                </div>
                <div className="text-xs text-muted">
                  {status === "speaking" ? t("speaking") : status === "listening" ? t("listening") : status === "evaluating" ? t("thinking") : ""}
                </div>
              </div>
            </div>
            <p className="mt-4 text-lg font-medium leading-snug">{q.question}</p>
            <p className="mt-2 text-xs text-muted">{q.why}</p>
            <div className="mt-4 flex flex-wrap gap-2">
              {status === "listening" ? (
                <button className="btn-ghost" onClick={stopListening}>
                  {t("stop")}
                </button>
              ) : (
                <button className="btn-ghost" onClick={listen} disabled={!canListen}>
                  {t("speakAnswer")}
                </button>
              )}
              <button className="btn-ghost" onClick={() => speak(q.question)}>
                {t("repeat")}
              </button>
              <button className="btn-ghost" onClick={next} disabled={idx >= plan.questions.length - 1}>
                {t("nextQuestion")} <Icon.arrow size={14} />
              </button>
            </div>
            <textarea className="mt-3 h-32 w-full rounded-xl border border-line p-3 text-sm" placeholder={t("typeAnswer")} value={answer} onChange={(e) => setAnswer(e.target.value)} />
            <button className="btn mt-2" onClick={submit} disabled={!answer.trim() || status === "evaluating"}>
              {t("getFeedback")}
            </button>
            <p className="mt-3 text-xs text-muted">{plan.caveat}</p>
          </div>
          <div className="space-y-3">
            <div className="card">
              <div className="text-xs font-medium text-muted">{t("scoresSoFar")}</div>
              <div className="mt-2 grid grid-cols-3 gap-2">
                {(["fit", "depth", "clarity"] as const).map((k) => (
                  <div key={k} className="stat">
                    <div className="label">{k}</div>
                    <div className="value text-brand-ink">{avg(k)}</div>
                  </div>
                ))}
              </div>
            </div>
            {done.map((e, i) => (
              <div key={i} className="card">
                <div className="text-xs text-muted">
                  {t("yourAnswer")} · fit {e.scores.fit} · depth {e.scores.depth} · clarity {e.scores.clarity}
                </div>
                <p className="mt-1 text-sm text-muted">{e.answer}</p>
                <p className="mt-2 text-sm">{e.feedback}</p>
                <p className="mt-2 text-sm font-medium">{t("followUp")}: {e.follow_up}</p>
              </div>
            ))}
            <div className="card">
              <div className="text-xs font-medium text-muted">{t("strongAnswer")}</div>
              <ul className="mt-1 list-disc pl-5 text-sm">
                {q.strong_answer_includes.map((s) => (
                  <li key={s}>{s}</li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

